import type { Directory, User } from "./types.ts";

export function grantsFor(user: User, directory: Directory): Set<string> {
  // Resolve each role entry and its parent chain; track visited roles to guard against cycles.
  const grants = new Set<string>();
  const visited = new Set<string>();
  for (const name of user.roles) {
    for (let role: string | undefined = name; role && !visited.has(role); role = directory[role]?.parent) {
      visited.add(role);
      for (const grant of directory[role]?.grants ?? []) grants.add(grant);
    }
  }
  return grants;
}
EOF
