  if (!report) return { status: 404, body: "Not found" };
  return { status: 200, body: report.body };
}
EOF
cat >> tests/reports.test.ts <<'EOF'
test("roles inherit grants through parent chains (ACCESS-284)",()=>{
  const dir={"report-reader":{grants:["report:download"]},auditor:{grants:[],parent:"report-reader"},senior:{grants:[],parent:"auditor"}};
  for(const role of ["auditor","senior"]) assert.equal(downloadReport({id:"u",roles:[role],denied:[]},"r1",dir,reports).status,200);
});
test("parent cycles terminate without granting access",()=>{
  const dir={a:{grants:[],parent:"b"},b:{grants:[],parent:"a"}};
  assert.equal(allows({id:"u",roles:["a"],denied:[]},"report:download",dir),false);
});
test("explicit denials override inherited grants",()=>{
  for(const role of ["reader","analyst"]) assert.equal(downloadReport({id:"u",roles:[role],denied:["report:download"]},"r1",directory,reports).status,403);
});
EOF
